const taxonomy = $json.output || $json;
const config = $('Config').item.json;
const locations = config.locations || ["Hong Kong", "Singapore", "Remote", "Australia"];
const maxQueries = config.maxApifyQueries || 30;

const priority = { 'Tier 1': 0, 'Tier 2': 1, 'Tier 3': 2 };
const tiers = []
  .concat((taxonomy.tier1_direct || []).map((e) => Object.assign({}, e, { tier: 'Tier 1' })))
  .concat((taxonomy.tier2_adjacent || []).map((e) => Object.assign({}, e, { tier: 'Tier 2' })))
  .concat((taxonomy.tier3_stretch || []).map((e) => Object.assign({}, e, { tier: 'Tier 3' })));

const queries = [];
for (const entry of tiers) {
  for (const location of locations) {
    queries.push({
      title: entry.title,
      tier: entry.tier,
      seniority: entry.seniority || '',
      alternateTitles: (entry.alternate_titles || []).join(', '),
      searchKeywords: (entry.search_keywords || []).join(', '),
      location: location,
      query: entry.title + ' ' + location,
    });
  }
}

queries.sort((a, b) => priority[a.tier] - priority[b.tier]);
const capped = queries.slice(0, maxQueries);
return capped.map((q) => ({ json: q }));

const queryMeta = $('Apify Query Loop').item.json;
return $input.all().map((item) => {
  const d = item.json || {};
  return {
    json: {
      queryTitle: queryMeta.title,
      queryLocation: queryMeta.location,
      tier: queryMeta.tier,
      seniority: queryMeta.seniority,
      alternateTitles: queryMeta.alternateTitles || '',
      searchKeywords: queryMeta.searchKeywords || '',
      title: d.title || d.jobTitle || d.position || '',
      company: d.companyName || d.company || d.organization || '',
      location: d.location || d.jobLocation || queryMeta.location,
      sourceUrl: d.jobUrl || d.url || d.link || '',
      description: (d.description || d.descriptionText || '').toString().slice(0, 500),
      postedAt: (d.postedAt || d.datePosted || d.postedDate || '').toString(),
    },
  };
});

const config = $('Config').item.json;
const maxAgeDays = config.postedWithinDays || 30;
const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000;

const STOPWORDS = new Set(['trade','trades','trading','trader','traders','director','directors','manager','managers','senior','officer','officers','head','heads','state','government','national','company','companies','client','clients','service','services','the','and','for','of']);

function sigWords(text) {
  return (text || '')
    .toLowerCase()
    .split(/[^a-z]+/)
    .filter((w) => w.length >= 5 && !STOPWORDS.has(w));
}

function isRelevant(d) {
  const vocab = new Set();
  for (const w of sigWords(d.queryTitle)) vocab.add(w);
  const alts = (d.alternateTitles || '').split(',');
  for (const alt of alts) for (const w of sigWords(alt)) vocab.add(w);
  const kws = (d.searchKeywords || '').split(',');
  for (const kw of kws) for (const w of sigWords(kw)) vocab.add(w);
  const listingWords = sigWords(d.title);
  const vocabOverlap = vocab.size === 0 || listingWords.some((w) => vocab.has(w));

  const titleLower = (d.title || '').toLowerCase();

  const isInvestmentRelated = /invest/.test(titleLower);

  const WRONG_FUNCTION = ['compliance', 'trading', 'trader', 'execution', 'operations', 'settlement', 'custody', 'audit', 'surveillance', 'regulatory', 'dealer', 'dealing', 'risk', 'kyc', 'aml', 'back office', 'middle office'];
  const hasWrongFunction = WRONG_FUNCTION.some((kw) => titleLower.includes(kw));

  const isTradeRole = /\btrade\b|\btrading\b/.test(titleLower) && !isInvestmentRelated;

  return isInvestmentRelated && !hasWrongFunction && !isTradeRole && vocabOverlap;
}

const seen = new Set();
const result = [];
for (const item of $input.all()) {
  const d = item.json || {};
  if (!d.company || !d.title || !d.sourceUrl) continue;
  const key = (d.company + '|' + d.title).toLowerCase().trim();
  if (seen.has(key)) continue;
  seen.add(key);
  if (d.postedAt) {
    const posted = Date.parse(d.postedAt);
    if (!isNaN(posted) && posted < cutoff) continue;
  }
  if (!isRelevant(d)) continue;
  result.push({ json: d, pairedItem: item.pairedItem });
}
return result;

const listing = $('Listings Loop').item.json;
const exa = $json || {};
const results = exa.results || [];

function normalize(s) { return (s || '').toString().toLowerCase().replace(/[^a-z0-9]/g, ''); }
const companyKey = normalize(listing.company);
const companyFrag = companyKey.slice(0, Math.min(6, companyKey.length));
const keywords = ['job', 'career', 'position', 'opening', 'vacan'];
const titleSlug = normalize(listing.title).slice(0, 12);

let match = null;
for (const r of results) {
  const url = r.url || '';
  let host = '';
  try { host = new URL(url).hostname; } catch (e) { continue; }
  const hostKey = normalize(host);
  const domainMatches = companyFrag.length > 2 && hostKey.includes(companyFrag);
  const pathLower = url.toLowerCase();
  const pathMatches = keywords.some((k) => pathLower.includes(k)) || pathLower.includes(titleSlug);
  if (domainMatches && pathMatches) { match = r; break; }
}
if (!match) {
  match = results.find((r) => {
    const pathLower = (r.url || '').toLowerCase();
    return keywords.some((k) => pathLower.includes(k)) && normalize(r.title || '').includes(companyFrag);
  }) || null;
}

return [{
  json: Object.assign({}, listing, {
    verified: !!match,
    verifiedUrl: match ? match.url : '',
    exaSnippet: match ? (match.text || '').toString().slice(0, 500) : '',
    exaResultsCount: results.length,
  }),
  pairedItem: 0,
}];
